package com.cbs.access;

import com.cbs.tenancy.*;
import com.cbs.tenancy.TenantModels.*;
import com.cbs.approvals.ApprovalModels.Action;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import tools.jackson.databind.json.JsonMapper;

/** Explicit lending authority. Platform administration is configuration authority, not credit authority. */
@Service
@ConditionalOnProperty(name="cbs.tenancy.enabled",havingValue="true",matchIfMissing=true)
public class LendingAccess {
 public enum Role {CREDIT_OFFICER,CREDIT_APPROVER,COLLECTIONS_OFFICER,FINANCE_OFFICER,AUDITOR}
 public enum Operation {CREDIT_REVIEW,CREDIT_RELEASE,LOAN_DISBURSE,LOAN_REPAY,LOAN_ACCRUE,LOAN_REVERSAL,LOAN_RESTRUCTURE,LOAN_IMPAIR,LOAN_WRITE_OFF,LOAN_FEE_ASSESS,LOAN_FEE_PAY,LOAN_FEE_WAIVE}
 public record Limit(@NotNull Operation operation,@NotNull @Pattern(regexp="[A-Z]{3}") String currency,@NotNull @Pattern(regexp="[0-9]{1,18}(\\.[0-9]{1,6})?") String perTransaction,@NotNull @Pattern(regexp="[0-9]{1,18}(\\.[0-9]{1,6})?") String dailyTotal){}
 public record Grant(@PositiveOrZero long expectedVersion,@NotNull UUID staffId,boolean active,boolean bankWide,@NotNull @Size(max=100) List<UUID> branches,@NotNull @Size(min=1,max=5) List<Role> roles,@NotNull @Size(max=100) List<@Valid Limit> limits,@NotBlank @Size(max=500) String reason){}
 public record Scope(UUID accountId,Operation operation,String currency,String amount,LocalDate businessDate){}
 private static final JsonMapper JSON=JsonMapper.builder().build();
 private final JdbcTemplate jdbc;private final TenantRepository tenants;private final AccessService access;
 public LendingAccess(JdbcTemplate jdbc,TenantRepository tenants,AccessService access){this.jdbc=jdbc;this.tenants=tenants;this.access=access;}
 private static TenantException deny(String code){return new TenantException(403,code,"Lending permission is not available for this bank and scope");}
 public Grant grant(Actor actor,UUID bank){access.requireAssignable(actor.issuer(),actor.subject());var rows=jdbc.queryForList("SELECT g.payload::text FROM platform.lending_access g JOIN platform.staff_identity s ON s.id=g.staff_id WHERE g.tenant_id=? AND s.issuer=? AND s.subject=? AND s.active AND g.active",String.class,bank,actor.issuer(),actor.subject());if(rows.isEmpty())throw deny("LENDING_ACCESS_DENIED");return JSON.readValue(rows.getFirst(),Grant.class);}
 public UUID branch(UUID bank,UUID account){var rows=jdbc.queryForList("SELECT ab.branch_id FROM platform.account_branch ab JOIN platform.branch b ON b.id=ab.branch_id AND b.tenant_id=ab.tenant_id AND b.active WHERE ab.tenant_id=? AND ab.account_id=?",UUID.class,bank,account);return rows.isEmpty()?null:rows.getFirst();}
 public Grant read(Actor actor,UUID bank,UUID account){var g=grant(actor,bank);if(account!=null){if(!jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.account_registry WHERE tenant_id=? AND id=?)",Boolean.class,bank,account))throw deny("LENDING_ACCESS_DENIED");if(!g.bankWide()&&!g.branches().contains(branch(bank,account)))throw deny("LENDING_BRANCH_DENIED");}return g;}
 public void role(Actor actor,UUID bank,UUID account,Role role){if(!read(actor,bank,account).roles().contains(role))throw deny("LENDING_ROLE_REQUIRED");}
 public String filter(Actor actor,UUID bank,String column){var g=read(actor,bank,null);if(g.bankWide())return "";if(g.branches().isEmpty())return " AND false";String ids=g.branches().stream().map(id->"'"+id+"'::uuid").collect(java.util.stream.Collectors.joining(","));return " AND "+column+" IN (SELECT ab.account_id FROM platform.account_branch ab JOIN platform.branch b ON b.id=ab.branch_id AND b.tenant_id=ab.tenant_id AND b.active WHERE ab.tenant_id='"+bank+"'::uuid AND ab.branch_id IN ("+ids+"))";}
 public void maker(Actor actor,UUID bank,Scope s){role(actor,bank,s.accountId(),switch(s.operation()){case CREDIT_REVIEW,CREDIT_RELEASE,LOAN_RESTRUCTURE->Role.CREDIT_OFFICER;default->Role.FINANCE_OFFICER;});}
 public void checker(Actor actor,UUID bank,Scope s,UUID request,boolean consume){
  var g=read(actor,bank,s.accountId());if(!g.roles().contains(Role.CREDIT_APPROVER))throw deny("LENDING_ROLE_REQUIRED");
  var cap=g.limits().stream().filter(l->l.operation()==s.operation()&&l.currency().equals(s.currency())).findFirst().orElseThrow(()->deny("LENDING_APPROVAL_LIMIT_REQUIRED"));var amount=new BigDecimal(s.amount());
  if(amount.compareTo(new BigDecimal(cap.perTransaction()))>0)throw deny("LENDING_APPROVAL_LIMIT_EXCEEDED");
  // Exclude this request for decision retries and delivery rechecks, but keep other approved/unposted decisions reserved.
  var used=jdbc.queryForObject("SELECT coalesce(sum(amount),0) FROM platform.lending_approval_usage WHERE tenant_id=? AND staff_id=? AND operation=? AND currency=? AND business_date=? AND request_id<>?",BigDecimal.class,bank,g.staffId(),s.operation().name(),s.currency(),s.businessDate(),request==null?new UUID(0,0):request);
  if(used.add(amount).compareTo(new BigDecimal(cap.dailyTotal()))>0)throw deny("LENDING_DAILY_APPROVAL_LIMIT_EXCEEDED");
  if(consume)jdbc.update("INSERT INTO platform.lending_approval_usage(request_id,tenant_id,staff_id,operation,currency,business_date,amount) VALUES (?,?,?,?,?,?,?) ON CONFLICT(request_id) DO NOTHING",request,bank,g.staffId(),s.operation().name(),s.currency(),s.businessDate(),amount);
 }
 public boolean scoped(Action action,UUID bank,Object input){if(Set.of(Action.CREDIT_REVIEW,Action.CREDIT_RELEASE,Action.LOAN_SERVICING,Action.LOAN_FEE).contains(action))return true;if(!Set.of(Action.CONTRACT_OPEN,Action.CONTRACT_EVENT,Action.CONTRACT_CORRECTION).contains(action))return false;var n=JSON.valueToTree(input);if(action==Action.CONTRACT_OPEN)return "LOAN".equals(n.path("type").asText());return jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.contract WHERE tenant_id=? AND id=? AND kind='LOAN')",Boolean.class,bank,UUID.fromString(n.path("contractId").asText()));}
 public Scope scope(UUID bank,Action action,Object input){var n=JSON.valueToTree(input);UUID account;String currency,amount;Operation op;LocalDate day;
  if(action==Action.CREDIT_REVIEW||action==Action.CREDIT_RELEASE){var rows=jdbc.queryForList("SELECT account_id,currency,payload FROM platform.credit_application WHERE tenant_id=? AND id=?",bank,UUID.fromString(n.path("applicationId").asText()));if(rows.isEmpty())throw deny("LENDING_ACCESS_DENIED");var r=rows.getFirst();account=(UUID)r.get("account_id");currency=r.get("currency").toString();amount=JSON.readTree(r.get("payload").toString()).path("principal").asText();op=Operation.valueOf(action.name());day=businessDate(bank);
  }else if(action==Action.CONTRACT_OPEN){account=UUID.fromString(n.path("accountId").asText());currency=currency(bank,account);amount=n.path("principal").asText();op=Operation.LOAN_DISBURSE;day=LocalDate.parse(n.path("startDate").asText());
  }else{var rows=jdbc.queryForList("SELECT account_id,position FROM platform.contract WHERE tenant_id=? AND id=? AND kind='LOAN'",bank,UUID.fromString(n.path("contractId").asText()));if(rows.isEmpty())throw deny("LENDING_ACCESS_DENIED");account=(UUID)rows.getFirst().get("account_id");currency=currency(bank,account);var position=JSON.readTree(rows.getFirst().get("position").toString());amount=new BigDecimal(position.path("principal").asText()).add(new BigDecimal(position.path("interest").asText())).toPlainString();day=LocalDate.parse(n.path("businessDate").asText());
   if(action==Action.LOAN_FEE){op=Operation.valueOf("LOAN_"+n.path("operation").asText());amount=n.path("amount").asText();}
   else if(action==Action.LOAN_SERVICING)op=Operation.valueOf("LOAN_"+n.path("operation").asText());
   else if(action==Action.CONTRACT_CORRECTION){op=Operation.LOAN_REVERSAL;var original=jdbc.queryForList("SELECT payload::text FROM platform.contract_delivery WHERE tenant_id=? AND contract_id=? AND id=? AND completed",String.class,bank,UUID.fromString(n.path("contractId").asText()),UUID.fromString(n.path("originalEventId").asText()));if(original.isEmpty())throw deny("LENDING_ACCESS_DENIED");var p=JSON.readTree(original.getFirst());amount=new BigDecimal(p.path("customerMovement").asText()).abs().max(new BigDecimal(p.path("after").path("interest").asText()).subtract(new BigDecimal(p.path("before").path("interest").asText())).abs()).toPlainString();}
   else{if(!Set.of("REPAY","ACCRUE").contains(n.path("kind").asText()))throw new TenantException(409,"CONTRACT_EVENT_INVALID","Unsupported loan operation");op=Operation.valueOf("LOAN_"+n.path("kind").asText());if(op==Operation.LOAN_REPAY)amount=n.path("amount").asText();}
  }return new Scope(account,op,currency,amount,day);
 }
 private String currency(UUID bank,UUID account){var rows=jdbc.queryForList("SELECT currency FROM platform.account_registry WHERE tenant_id=? AND id=?",String.class,bank,account);if(rows.isEmpty())throw deny("LENDING_ACCESS_DENIED");return rows.getFirst();}
 private LocalDate businessDate(UUID bank){return jdbc.queryForObject("SELECT business_date FROM platform.bank_settings WHERE tenant_id=?",LocalDate.class,bank);}
 public void record(UUID request,UUID bank,Scope s){jdbc.update("INSERT INTO platform.lending_approval_scope(request_id,tenant_id,account_id,payload) VALUES (?,?,?,?::jsonb)",request,bank,s.accountId(),JSON.writeValueAsString(s));}
 public Scope request(UUID request){var rows=jdbc.queryForList("SELECT payload::text FROM platform.lending_approval_scope WHERE request_id=?",String.class,request);return rows.isEmpty()?null:JSON.readValue(rows.getFirst(),Scope.class);}
 public void readRequest(Actor actor,UUID request){var rows=jdbc.queryForList("SELECT tenant_id,account_id FROM platform.lending_approval_scope WHERE request_id=?",request);if(rows.isEmpty())throw deny("LENDING_ACCESS_DENIED");read(actor,(UUID)rows.getFirst().get("tenant_id"),(UUID)rows.getFirst().get("account_id"));}
 public void validateGrant(Actor actor,Tenant bank,Grant g){AccessService.admin(actor);if(bank.version()!=g.expectedVersion())throw new TenantException(409,"STALE_VERSION","Refresh the bank");var staff=access.staff(g.staffId(),false);if(!staff.issuer().equals(actor.issuer())||g.active()&&!staff.active())throw deny("LENDING_ACCESS_DENIED");if(new HashSet<>(g.roles()).size()!=g.roles().size()||new HashSet<>(g.branches()).size()!=g.branches().size()||g.bankWide()!=g.branches().isEmpty()||!g.roles().contains(Role.CREDIT_APPROVER)&&!g.limits().isEmpty())throw deny("LENDING_GRANT_INVALID");for(UUID branch:g.branches())if(g.active()&&!jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.branch WHERE tenant_id=? AND id=? AND active)",Boolean.class,bank.id(),branch))throw deny("LENDING_BRANCH_DENIED");var seen=new HashSet<String>();for(var l:g.limits()){try{int scale=Currency.getInstance(l.currency()).getDefaultFractionDigits();var per=new BigDecimal(l.perTransaction());var daily=new BigDecimal(l.dailyTotal());if(per.signum()<=0||per.scale()>scale||daily.scale()>scale||daily.compareTo(per)<0||!seen.add(l.currency()+":"+l.operation()))throw new IllegalArgumentException();}catch(IllegalArgumentException e){throw deny("LENDING_GRANT_INVALID");}}}
 public void applyGrant(Actor actor,UUID bankId,Grant g,UUID approval){var bank=tenants.get(bankId,true);validateGrant(actor,bank,g);if(access.staff(g.staffId(),false).subject().equals(actor.subject()))throw deny("LENDING_SELF_GRANT_APPROVAL");jdbc.update("INSERT INTO platform.lending_access(tenant_id,staff_id,active,payload,approval_id) VALUES (?,?,?,?::jsonb,?) ON CONFLICT(tenant_id,staff_id) DO UPDATE SET active=excluded.active,payload=excluded.payload,approval_id=excluded.approval_id",bankId,g.staffId(),g.active(),JSON.writeValueAsString(g),approval);jdbc.update("INSERT INTO platform.lending_access_event(approval_id,tenant_id,staff_id,payload) VALUES (?,?,?,?::jsonb)",approval,bankId,g.staffId(),JSON.writeValueAsString(g));tenants.change(bank,bank.status(),bank.displayName(),bank.defaultLanguage());tenants.audit(actor,bankId,"LENDING_ACCESS_CHANGED",bank.version()+1,bank.status(),bank.status(),g.reason(),null,null,Map.of("staffId",g.staffId(),"active",g.active(),"approvalId",approval));}
 public List<Map<String,Object>> banks(Actor actor){return jdbc.queryForList("SELECT t.id,t.display_name AS \"displayName\",t.status FROM platform.tenant t JOIN platform.lending_access g ON g.tenant_id=t.id JOIN platform.staff_identity s ON s.id=g.staff_id WHERE s.issuer=? AND s.subject=? AND s.active AND g.active ORDER BY t.display_name,t.id LIMIT 100",actor.issuer(),actor.subject());}
 public Map<String,Object> context(Actor actor,UUID bank){var g=read(actor,bank,null);var b=tenants.get(bank,false);return Map.of("id",bank,"displayName",b.displayName(),"status",b.status(),"version",b.version(),"grant",g);}
 public Map<String,Object> report(Actor actor,UUID bank,int limit,int offset){AccessService.admin(actor);AccessService.page(limit,offset);var b=tenants.get(bank,false);return Map.of("version",b.version(),"items",jdbc.query("SELECT g.payload,s.display_name,s.subject,s.active FROM platform.lending_access g JOIN platform.staff_identity s ON s.id=g.staff_id WHERE g.tenant_id=? AND s.issuer=? ORDER BY s.display_name,s.id LIMIT ? OFFSET ?",(r,n)->Map.of("grant",JSON.readValue(r.getString(1),Grant.class),"displayName",r.getString(2),"subject",r.getString(3),"staffActive",r.getBoolean(4)),bank,actor.issuer(),limit,offset),"total",jdbc.queryForObject("SELECT count(*) FROM platform.lending_access g JOIN platform.staff_identity s ON s.id=g.staff_id WHERE g.tenant_id=? AND s.issuer=?",Long.class,bank,actor.issuer()),"branches",jdbc.queryForList("SELECT id,code,display_name AS name,active FROM platform.branch WHERE tenant_id=? ORDER BY code,id",bank),"history",jdbc.query("SELECT e.payload,a.maker_subject,a.reviewer_subject,a.decided_at,si.display_name,si.subject FROM platform.lending_access_event e JOIN platform.approval_request a ON a.id=e.approval_id JOIN platform.staff_identity si ON si.id=e.staff_id WHERE e.tenant_id=? AND a.issuer=? ORDER BY e.sequence DESC LIMIT ? OFFSET ?",(r,n)->Map.of("grant",JSON.readValue(r.getString(1),Grant.class),"maker",r.getString(2),"checker",r.getString(3),"at",r.getTimestamp(4).toInstant(),"displayName",r.getString(5),"subject",r.getString(6)),bank,actor.issuer(),limit,offset),"historyTotal",jdbc.queryForObject("SELECT count(*) FROM platform.lending_access_event e JOIN platform.approval_request a ON a.id=e.approval_id WHERE e.tenant_id=? AND a.issuer=?",Long.class,bank,actor.issuer()));}
}
